<?php
require_once __DIR__ . '/../config/db.php'; require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../services/userService.php';
startSecureSession(); if (isLoggedIn()) { header('Location: profile.php', true, 303); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verifyCsrfToken($_POST); try { registerUser(openDatabase(), $_POST); header('Location: login.php?registered=1', true, 303); exit; } catch (InvalidArgumentException $e) { $error = $e->getMessage(); } catch (Throwable $e) { error_log($e->getMessage()); $error = 'Account could not be created.'; } }
require __DIR__ . '/../includes/header.php'; require __DIR__ . '/../includes/nav.php'; ?>
<main class="container py-4"><h1>Create account</h1><?php if ($error): ?><div class="alert alert-danger"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
<form method="post" class="col-md-7"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrfToken(), ENT_QUOTES, 'UTF-8') ?>"><div class="mb-3"><label class="form-label">Full name<input class="form-control" name="full_name" required maxlength="120" value="<?= htmlspecialchars((string)($_POST['full_name'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></label></div><div class="mb-3"><label class="form-label">Email<input class="form-control" type="email" name="email" required maxlength="254" value="<?= htmlspecialchars((string)($_POST['email'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></label></div><div class="mb-3"><label class="form-label">Password<input class="form-control" type="password" name="password" required minlength="12"></label><div class="form-text">At least 12 characters.</div></div><div class="mb-3"><label class="form-label">Confirm password<input class="form-control" type="password" name="confirm_password" required></label></div><fieldset class="mb-3"><legend class="fs-6">Account type</legend><label class="me-3"><input type="radio" name="role" value="Student" required <?= ($_POST['role'] ?? 'Student') === 'Student' ? 'checked' : '' ?>> Student</label><label><input type="radio" name="role" value="Tutor" <?= ($_POST['role'] ?? '') === 'Tutor' ? 'checked' : '' ?>> Tutor</label></fieldset><button class="btn btn-primary">Create account</button></form></main><?php require __DIR__ . '/../includes/footer.php'; ?>
